document.addEventListener("DOMContentLoaded", () => {

  /* ========= عناصر أساسية ========= */
  const cards = document.querySelectorAll(".video-card");

  const playerOverlay = document.getElementById("playerOverlay");
  const playerTitle   = document.getElementById("playerTitle");
  const playerVideo   = document.getElementById("playerVideo");
  const playerIframe  = document.getElementById("playerIframe");
  const playerClose   = document.getElementById("playerClose");

  const episodesRow   = document.getElementById("episodesRow");
  const episodesList  = document.getElementById("episodesList");

  const latestBtn     = document.getElementById("latestBtn");
  const latestOverlay = document.getElementById("latestOverlay");
  const latestGrid    = document.getElementById("latestGrid");
  const latestClose   = document.getElementById("latestClose");

  /* ========= أدوات ========= */
  function clearPlayer() {
    playerVideo.pause();
    playerVideo.removeAttribute("src");
    playerIframe.removeAttribute("src");
    playerVideo.style.display = "none";
    playerIframe.style.display = "none";
  }

  function playUrl(url, title) {
    if (!url) return;

    clearPlayer();
    playerTitle.textContent = title;

    if (/\.(mp4|m3u8|ts)(\?|$)/i.test(url)) {
      playerVideo.src = url;
      playerVideo.style.display = "block";
    } else {
      playerIframe.src = url;
      playerIframe.style.display = "block";
    }
  }

  /* ========= تشغيل الكرت ========= */
  cards.forEach(card => {
    card.addEventListener("click", () => {

      const title = card.dataset.title || "فيديو";
      const eps   = card.querySelectorAll(".ep-data");

      playerOverlay.classList.add("active");
      episodesList.innerHTML = "";
      episodesRow.style.display = "none";

      if (!eps.length) return;

      episodesRow.style.display = "flex";

      eps.forEach((ep, i) => {
        const btn = document.createElement("button");
        btn.className = "ep-pill";
        btn.textContent = ep.dataset.label || `حلقة ${i + 1}`;

        btn.onclick = () => {
          episodesList.querySelectorAll(".ep-pill")
            .forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          playUrl(ep.dataset.video, `${title} — ${btn.textContent}`);
        };

        episodesList.appendChild(btn);
      });

      // تشغيل آخر حلقة تلقائي
      const lastBtn = episodesList.lastElementChild;
      lastBtn.classList.add("active");
      playUrl(
        eps[eps.length - 1].dataset.video,
        `${title} — ${lastBtn.textContent}`
      );
      lastBtn.scrollIntoView({ behavior: "smooth", inline: "end" });
    });
  });

  /* ========= إغلاق المشغل ========= */
  playerClose.onclick = () => {
    playerOverlay.classList.remove("active");
    clearPlayer();
  };

  /* ========= أحدث الإضافات ========= */
  if (latestBtn) {
    latestBtn.onclick = () => {

      latestGrid.innerHTML = "";
      let latestItems = [];

      document.querySelectorAll(".video-card").forEach(card => {
        const title = card.dataset.title || "بدون عنوان";
        const img   = card.querySelector("img")?.src;
        const eps   = card.querySelectorAll(".ep-data");

        eps.forEach(ep => {
          const label = ep.dataset.label || "";
          if (!label.includes("🆕")) return;

          latestItems.push({
            title,
            img,
            label,
            video: ep.dataset.video,
            added: new Date(ep.dataset.added || "2000-01-01")
          });
        });
      });

      // ترتيب الأحدث
      latestItems.sort((a, b) => b.added - a.added);

      latestItems.forEach(item => {
        const box = document.createElement("div");
        box.className = "latest-card";
        box.innerHTML = `
          <div class="latest-img">
            <img src="${item.img}">
            <span class="latest-badge">جديد</span>
          </div>
          <div class="latest-info">
            <b>${item.title}</b>
            <small>${item.label}</small>
          </div>
        `;

        box.onclick = () => {
          latestOverlay.style.display = "none";
          playerOverlay.classList.add("active");
          playUrl(item.video, `${item.title} — ${item.label}`);
        };

        latestGrid.appendChild(box);
      });

      latestOverlay.style.display = "block";
    };
  }

  if (latestClose) {
    latestClose.onclick = () => {
      latestOverlay.style.display = "none";
    };
  }

});
